import { useEffect, useRef, useState } from 'react';

import { Button, Heading, Paragraph } from '@hexa-ui/components';
import { styled } from '@hexa-ui/theme';
import { Alert } from 'components';
import { useToast } from 'contexts';
import {
  BRAND_POWER_CONTEXT_BANNER_FADE_OUT_DURATION,
  BrandPowerContextBanner,
} from 'pages/pillars/PortfolioBrand/BrandPowerBookExport/components/BrandPowerContextBanner';

import { StyledContainer, StyledSection } from '../../ComponentsPage.styles';

const AlertExampleContainer = styled('div', {
  display: 'flex',
  flexDirection: 'column',
  gap: '16px',
});

const StyledBrandPowerContextBannerContainer = styled('div', {
  display: 'flex',
  flexDirection: 'column',
  gap: '12px',
  width: '100%',
});

const StyledBrandPowerContextBannerCompactRow = styled('div', {
  display: 'flex',
  flexDirection: 'column',
  gap: '8px',
  width: '100%',
  alignItems: 'flex-start',
});

const StyledBrandPowerContextBannerCompactItem = styled('div', {
  width: '100%',
